const LINKS = [["UC-1","FR-1"],["UC-1","FR-2"],["UC-2","FR-3"],["UC-2","FR-5"],["UC-4","FR-5"],["UC-4","FR-6"],["UC-3","FR-9"]];
function matrix(ucs, frs, links) {
  return ucs.map(function (u) { return frs.map(function (f) { return links.some(function (l) { return l[0] === u && l[1] === f; }); }); });
}
function shared(links) {
  var by = {};
  links.forEach(function (l) { by['#' + l[1]] = by['#' + l[1]] || {}; by['#' + l[1]][l[0]] = true; });
  return Object.keys(by).filter(function (k) { return Object.keys(by[k]).length > 1; }).map(function (k) { return k.slice(1); }).sort();
}
function emptyRows(ucs, links) {
  return ucs.filter(function (u) { return !links.some(function (l) { return l[0] === u; }); });
}
